with with_window as (select a.*, pr.id as promo_id, pr.promo_code, pr.discount_pct from orders a inner join promotions pr on a.channel <=> pr.channel and a.order_date between pr.starts_on and pr.ends_on) select date_trunc('quarter', order_date) as quarter_start, status, round(sum(promo_id) / nullif(count(case when status = 'RETURNED' then 1 end), 0), 2) as promo_id_per_returned, percentile_approx(shipping_fee, 0.5) as shipping_fee_p50, max(promo_id) as max_promo_id, count(*) filter (where status = 'PENDING') as pending_rows from with_window group by date_trunc('quarter', order_date), status order by status desc;
